package com.peertutoring.ui;

import com.peertutoring.model.Student;import com.peertutoring.model.Subject;import com.peertutoring.service.TutorService;import com.peertutoring.service.SessionService;
import javax.swing.*;import javax.swing.border.EmptyBorder;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.sql.SQLException;import java.time.LocalDateTime;import java.time.format.DateTimeParseException;import java.util.List;

public class TutorSearchFrame extends JFrame {
 private final Student student;private final TutorService tutorService=new TutorService();private final SessionService sessionService=new SessionService();private final JComboBox<Subject> subjectBox=new JComboBox<>();private final DefaultTableModel model=new DefaultTableModel(new String[]{"Student ID","Tutor name","Email","Semester"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable table=new JTable(model);private final JButton searchButton=new JButton("Search tutors"),requestButton=new JButton("Request session");
 public TutorSearchFrame(Student student){this.student=student;setTitle("PeerTutoringSystems | Find a Tutor");setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE);setSize(850,560);setLocationRelativeTo(null);JPanel root=new JPanel(new BorderLayout(12,16));root.setBorder(new EmptyBorder(24,28,24,28));root.setBackground(new Color(245,247,251));JLabel title=new JLabel("Find a peer tutor");title.setFont(new Font("SansSerif",Font.BOLD,25));JPanel top=new JPanel(new BorderLayout(8,8));top.setOpaque(false);top.add(title,BorderLayout.NORTH);JPanel filter=new JPanel(new FlowLayout(FlowLayout.LEFT,8,4));filter.setOpaque(false);filter.add(new JLabel("Subject:"));subjectBox.setPreferredSize(new Dimension(250,32));filter.add(subjectBox);filter.add(searchButton);top.add(filter,BorderLayout.SOUTH);root.add(top,BorderLayout.NORTH);table.setRowHeight(30);table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);table.setFillsViewportHeight(true);root.add(new JScrollPane(table),BorderLayout.CENTER);JPanel bottom=new JPanel(new FlowLayout(FlowLayout.RIGHT));bottom.setOpaque(false);requestButton.setBackground(new Color(48,88,166));requestButton.setForeground(Color.WHITE);bottom.add(requestButton);root.add(bottom,BorderLayout.SOUTH);setContentPane(root);searchButton.addActionListener(e->search());requestButton.addActionListener(e->request());loadSubjects();}
 private void loadSubjects(){try{for(Subject s:tutorService.getAllSubjects())subjectBox.addItem(s);}catch(SQLException ex){dbError();}}
 private void search(){Subject s=(Subject)subjectBox.getSelectedItem();if(s==null){JOptionPane.showMessageDialog(this,"No subjects are available.");return;}try{model.setRowCount(0);List<Student> tutors=tutorService.searchTutorsBySubject(s.getSubjectId(),student.getStudentId());for(Student t:tutors)model.addRow(new Object[]{t.getStudentId(),t.getFullName(),t.getEmail(),t.getSemester()});if(tutors.isEmpty())JOptionPane.showMessageDialog(this,"No other students are currently offering this subject.","No tutors found",JOptionPane.INFORMATION_MESSAGE);}catch(SQLException ex){dbError();}catch(IllegalArgumentException ex){JOptionPane.showMessageDialog(this,ex.getMessage(),"Search error",JOptionPane.WARNING_MESSAGE);}}
 private void request(){int row=table.getSelectedRow();Subject s=(Subject)subjectBox.getSelectedItem();if(row<0){JOptionPane.showMessageDialog(this,"Select a tutor first.");return;}if(s==null)return;int tutorId=(Integer)model.getValueAt(row,0);if(tutorId==student.getStudentId()){JOptionPane.showMessageDialog(this,"You cannot request a session with yourself.");return;}JTextField message=new JTextField();JTextField schedule=new JTextField();JPanel p=new JPanel(new GridLayout(0,1,5,5));p.add(new JLabel("Message (optional, max 500 characters):"));p.add(message);p.add(new JLabel("Scheduled date/time (optional; yyyy-MM-ddTHH:mm):"));p.add(schedule);int answer=JOptionPane.showConfirmDialog(this,p,"Request a tutoring session",JOptionPane.OK_CANCEL_OPTION,JOptionPane.PLAIN_MESSAGE);if(answer!=JOptionPane.OK_OPTION)return;if(message.getText().length()>500){JOptionPane.showMessageDialog(this,"Message cannot exceed 500 characters.");return;}LocalDateTime at=null;try{if(!schedule.getText().trim().isEmpty())at=LocalDateTime.parse(schedule.getText().trim());}catch(DateTimeParseException ex){JOptionPane.showMessageDialog(this,"Use date/time format yyyy-MM-ddTHH:mm, for example 2026-11-05T14:30.","Invalid date/time",JOptionPane.WARNING_MESSAGE);return;}try{sessionService.requestSession(student.getStudentId(),tutorId,s.getSubjectId(),at,message.getText());JOptionPane.showMessageDialog(this,"Session request sent.","Success",JOptionPane.INFORMATION_MESSAGE);}catch(SQLException ex){dbError();}catch(IllegalArgumentException ex){JOptionPane.showMessageDialog(this,ex.getMessage(),"Request failed",JOptionPane.WARNING_MESSAGE);}}
 private void dbError(){JOptionPane.showMessageDialog(this,"Unable to access the data right now. Check the database connection.","Database error",JOptionPane.ERROR_MESSAGE);}
}
